mapper.sql:
WHERE achievement.achievement_type = 'LECTURE_IMPROVEMENT'
    AND achievement.deleted_yn = 'N'

    AND achievement.management_no = #{criteria.normalizedManagementNo}


    AND achievement.management_item_code = #{criteria.normalizedManagementItemCode}


    AND detail.academic_year = #{criteria.academicYear}


    AND detail.semester_code = CAST(#{criteria.semester} AS varchar)


    AND achievement.achievement_status = #{criteria.normalizedAchievementStatus}

mapper.select:
SELECT
FROM education_achievements achievement JOIN lecture_improvement_achievement_details detail ON detail.achievement_id = achievement.achievement_id JOIN users owner ON owner.user_id = achievement.teacher_user_id
ORDER BY achievement.achievement_date DESC, achievement.achievement_id DESC LIMIT #{criteria.safePageSize} OFFSET #{criteria.offset}
